import Foundation

// Worksheet / structure mutations, ported from the handlers in src/App.tsx
// (handleUpdateDirectActual, handleCopyMonthValues, handleAddGroup, …) so both builds
// change a shared vault in the same way.

/// Group colors used for new groups (ZEN_PALETTE in src/data/templates.ts).
enum ZenGroupPalette {
    static let colors = ["#3f704d", "#b9432f", "#3f6e8c", "#b8862d", "#8a6fb0",
                         "#5b7f4a", "#c46d5e", "#d97aa6", "#4c7a7b", "#7a746b"]
}

enum KobanID {
    /// `prefix-<ms timestamp>-<4 random chars>`, like the ids generated by the Windows build.
    static func make(_ prefix: String, suffix: Bool = true) -> String {
        let ms = Int(Date().timeIntervalSince1970 * 1000)
        guard suffix else { return "\(prefix)-\(ms)" }
        let chars = "abcdefghijklmnopqrstuvwxyz0123456789"
        let rand = String((0..<4).map { _ in chars.randomElement()! })
        return "\(prefix)-\(ms)-\(rand)"
    }
}

extension LedgerState {
    /// True when the month has any budget or actual (previousMonthHasData in App.tsx).
    func monthHasData(monthKey: String, workspace: ActiveWorkspace) -> Bool {
        let s = monthSummary(monthKey: monthKey, workspace: workspace)
        return s.incomeBudget > 0 || s.incomeActual > 0 || s.totalOutflowBudget > 0 || s.totalOutflowActual > 0
    }

    /// Sets (or clears with `nil`) the direct Actual override of a category for one month.
    mutating func setDirectActual(_ amount: Double?, categoryId: String, monthKey: String) {
        if let idx = monthlyBudgets.firstIndex(where: { $0.monthKey == monthKey && $0.categoryId == categoryId }) {
            monthlyBudgets[idx].directActual = amount
        } else {
            let budget = categories.first(where: { $0.id == categoryId })?.defaultBudget ?? 0
            monthlyBudgets.append(MonthlyBudgetEntry(monthKey: monthKey, categoryId: categoryId,
                                                     budget: budget, directActual: amount))
        }
    }

    mutating func renameCategory(_ categoryId: String, to name: String) {
        guard let idx = categories.firstIndex(where: { $0.id == categoryId }) else { return }
        categories[idx].name = name
    }

    /// Toggles the recurring flag and creates / removes the linked monthly recurring rule.
    /// Returns the new flag, or nil when the category does not exist.
    @discardableResult
    mutating func toggleCategoryRecurring(_ categoryId: String, monthKey: String) -> Bool? {
        guard let cIdx = categories.firstIndex(where: { $0.id == categoryId }) else { return nil }
        let cat = categories[cIdx]
        let next = !(cat.isRecurring ?? false)
        categories[cIdx].isRecurring = next

        let current = monthlyBudgets.first(where: { $0.monthKey == monthKey && $0.categoryId == categoryId })
        let effectiveBudget = (current?.budget).flatMap { $0 != 0 ? $0 : nil } ?? cat.defaultBudget

        if next {
            if let rIdx = recurringRules.firstIndex(where: { $0.categoryId == categoryId }) {
                recurringRules[rIdx].active = true
                if recurringRules[rIdx].amount == 0 { recurringRules[rIdx].amount = effectiveBudget }
            } else {
                recurringRules.append(RecurringRule(
                    id: "rec-cat-\(categoryId)",
                    mode: cat.mode,
                    type: cat.kind == .income ? .income : .expense,
                    categoryId: cat.id,
                    description: cat.name,
                    amount: effectiveBudget,
                    frequency: .monthly,
                    dayOfMonth: cat.kind == .income ? 25 : 1,
                    taxRate: cat.taxRate ?? 0,
                    deductiblePct: cat.deductiblePct ?? 100,
                    active: true
                ))
            }
        } else {
            recurringRules.removeAll { $0.categoryId == categoryId }
        }
        return next
    }

    /// Deletes a category with its monthly entries and transactions.
    mutating func deleteCategory(_ categoryId: String) {
        categories.removeAll { $0.id == categoryId }
        monthlyBudgets.removeAll { $0.categoryId == categoryId }
        transactions.removeAll { $0.categoryId == categoryId }
    }

    /// Deletes a group and everything inside it.
    mutating func deleteGroup(_ groupId: String) {
        let catIds = Set(categories.filter { $0.groupId == groupId }.map(\.id))
        groups.removeAll { $0.id == groupId }
        categories.removeAll { $0.groupId == groupId }
        monthlyBudgets.removeAll { catIds.contains($0.categoryId) }
        transactions.removeAll { catIds.contains($0.categoryId) }
    }

    mutating func addCategory(groupId: String, mode: LedgerMode, kind: CategoryKind,
                              name: String, budget: Double, monthKey: String) {
        let cat = CategoryItem(
            id: KobanID.make("cat"),
            groupId: groupId,
            mode: mode,
            name: name,
            kind: kind,
            defaultBudget: budget,
            taxRate: 0,
            deductiblePct: 100,
            order: categories.filter { $0.groupId == groupId }.count
        )
        categories.append(cat)
        monthlyBudgets.append(MonthlyBudgetEntry(monthKey: monthKey, categoryId: cat.id, budget: budget))
    }

    mutating func addGroup(mode: LedgerMode, name: String, kind: CategoryKind, column: Int) {
        let color = kind == .income
            ? "#3f704d"
            : ZenGroupPalette.colors[groups.count % ZenGroupPalette.colors.count]
        groups.append(CategoryGroup(
            id: KobanID.make("grp", suffix: false),
            mode: mode,
            name: name,
            kind: kind,
            color: color,
            column: column,
            order: groups.filter { $0.mode == mode }.count
        ))
    }

    /// Copies the active month's planned budgets into all 12 months of the active year.
    mutating func applyBudgetsToAllMonths(from monthKey: String) {
        let year = settings.activeYear
        for cat in categories {
            let budget = monthlyBudgets.first(where: { $0.monthKey == monthKey && $0.categoryId == cat.id })?.budget
                ?? cat.defaultBudget
            for m in 1...12 {
                let mk = MonthKey.format(year: year, month: m)
                if let idx = monthlyBudgets.firstIndex(where: { $0.monthKey == mk && $0.categoryId == cat.id }) {
                    monthlyBudgets[idx].budget = budget
                } else {
                    monthlyBudgets.append(MonthlyBudgetEntry(monthKey: mk, categoryId: cat.id, budget: budget))
                }
            }
        }
    }

    /// Copies budgets (and optionally actuals, as direct overrides) from one month to another.
    /// Returns the number of categories copied.
    @discardableResult
    mutating func copyMonthValues(from source: String, to target: String, scope: MonthCopyScope,
                                  overwriteExisting: Bool, navigateToTarget: Bool = false,
                                  disableFutureConfirm: Bool = false) -> Int {
        var sourceRows: [String: (budget: Double, actual: Double)] = [:]
        for group in monthSummary(monthKey: source, workspace: .combined).groups {
            for row in group.rows { sourceRows[row.category.id] = (row.budget, row.actual) }
        }

        var copied = 0
        for cat in categories {
            guard let src = sourceRows[cat.id] else { continue }
            let actual: Double? = scope == .budgetsAndActuals ? src.actual : nil
            if let idx = monthlyBudgets.firstIndex(where: { $0.monthKey == target && $0.categoryId == cat.id }) {
                let existing = monthlyBudgets[idx]
                let hasNonZero = existing.budget != 0 || (existing.directActual ?? 0) != 0
                if !overwriteExisting && hasNonZero { continue }
                monthlyBudgets[idx].budget = src.budget
                monthlyBudgets[idx].directActual = actual
            } else {
                monthlyBudgets.append(MonthlyBudgetEntry(monthKey: target, categoryId: cat.id,
                                                         budget: src.budget, directActual: actual))
            }
            copied += 1
        }

        if disableFutureConfirm { settings.confirmBeforeMonthCopy = false }
        if navigateToTarget {
            let parts = target.split(separator: "-").compactMap { Int($0) }
            if parts.count == 2 {
                settings.activeYear = parts[0]
                settings.activeMonth = parts[1]
            }
        }
        return copied
    }

    /// Logs a transaction; clears a direct Actual override for its category & month so the
    /// new entry counts (handleAddTransaction).
    mutating func addTransaction(_ tx: TransactionItem) {
        for i in monthlyBudgets.indices
        where monthlyBudgets[i].monthKey == tx.monthKey && monthlyBudgets[i].categoryId == tx.categoryId {
            monthlyBudgets[i].directActual = nil
        }
        transactions.insert(tx, at: 0)
    }
}
